class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        vector<int> seen(256, -1);
        int left = 0, best = 0;
        for (int right = 0; right < s.size(); right++) {
            left = max(left, seen[s[right]] + 1);
            seen[s[right]] = right;
            best = max(best, right - left + 1);
        }
        return best;
    }
};
